Method.Implementation:
#dim tSC As %Status=$$$OK $$$TRACE("Inside Method ProcessHttpsRequest")
Set httprequest=##class(%Net.HttpRequest).%New()
Set httprequest.Location = ..Adapter.URL $$$TRACE("URL: "_httprequest.Location) Set httprequest.SSLConfiguration = ..Adapter.SSLConfig $$$TRACE("SSL Config: "_httprequest.SSLConfiguration)
Set httprequest.Https="1"
Set httprequest.Location = pRequest.url do httprequest.SetHeader("Content-Type","application/x-www-form-urlencoded") $$$TRACE(" Set form Data ")
do httprequest.InsertFormData("grant_type",pRequest.form1) do httprequest.InsertFormData("resource",pRequest.form2) do httprequest.InsertFormData("client_id",pRequest.form3) do httprequest.InsertFormData("client_secret",pRequest.form4)
try {
$$$TRACE(" POST message ") s postStatus = httprequest.Post(pRequest.url) $$$TRACE("Resp Status: "_postStatus) if (postStatus =1){ $$$TRACE(" Webcollect Azure service..Post Successful.") set len = httprequest.HttpResponse.ContentLength set respData = httprequest.HttpResponse.Data.Read() $$$TRACE("RESP DATA : "_respData)
set response=httprequest.HttpResponse $$$TRACE("StatusLine: "_response.StatusLine) do ..constructResponse(response,.jwtResponse)
set pResponse=jwtResponse //Do ##class(IHC.ITF.ITFCOMMON.Utility).ResetError(context.configName)
}else{ set errTxt = " RETRY. Webcollect Azure TOKEN service post request failed." $$$TRACE(" Post Failed.. " _ errTxt) set status=##class(IHC.ITF.ITFCOMMON.Utility).RetryCheckError(..%ConfigName,errTxt_". Retrying...")
} } catch e { $$$TRACE(" Unknown Exception: " _ e) set errTxt = $System.Status.GetErrorText("Unknown Exception while calling Webcollect Https service. "_e) Set tSC = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError(..%ConfigName,errTxt)
} quit tSC

Set tSC=$$$OK
If $IsObject(pHttpResponse.Data) {
	Set tStream=pHttpResponse.Data
} Else {
	Set tStream=##class(%GlobalBinaryStream).%New()
	Set tSC=tStream.Write(pHttpResponse.Data)  Quit:$$$ISERR(tSC) tSC
}
Set pResponse=##class(EnsLib.HTTP.GenericMessage).%New(tStream,,pHttpResponse)
Do pResponse.HTTPHeaders.SetAt(pHttpResponse.StatusLine,"StatusLine")
Quit tSC
